/**
 * DeviceBinding
 *
 * What a device write carries: the agents the device may reach.
 */
export type DeviceBinding = {
    /**
     * Agents
     *
     * The agents this device is bound to, by name. The first is the agent a conversation starts on and the rest are the ones switch_agent can reach. Every name has to be an agent that exists, or the write is refused.
     */
    agents: Array<string>;
};

/**
 * DefaultAgentName
 *
 * What a default-agent write carries. Clearing it is the DELETE,
 * not a null here: one way to say a thing.
 */
export type DefaultAgentName = {
    /**
     * Name
     *
     * The agent an unbound device reaches. It has to be an agent that exists. To unset it, DELETE this resource, which leaves the devices map as the allowlist.
     */
    name: string;
};

/**
 * SecretValue
 *
 * What a secret write carries: the credential itself, the only
 * plaintext this API ever accepts.
 */
export type SecretValue = {
    /**
     * Secret
     *
     * The credential, in plaintext, stored encrypted under the newest key in VINGA_MASTER_KEY. It crosses the connection as itself, which is why the whole API belongs on a loopback connection or behind TLS. It is never read back: a read names the slot and masks the value. It may not be empty.
     */
    secret: string;
};

/**
 * FieldError
 *
 * One field of the submitted body that a refusal names.
 */
export type FieldError = {
    /**
     * Path
     *
     * Which part of the submitted body this is about, as an RFC 6901 JSON Pointer into it: `/filler/phrases` is that field of that object, `/mcp/0` is that position of that list, and the empty string is the body as a whole. Only names this server declares and positions appear in it. A key the request invented is never one of them: an unrecognized key, an option a provider passes through, an entry of an `env` or `headers` map. A key is as good a place to paste a credential as a value is, so the pointer stops at the nearest enclosing place this server can name, which for a key written at the top of a fragment is the fragment itself.
     */
    path: string;
    /**
     * Message
     *
     * What is wrong with it, in the same words the corresponding line of `detail` uses: the two are rendered from one computation, so a client showing this beside the field and one showing the whole sentence say the same thing. Like `detail`, it names a rule and never quotes the value it rejected or a key the request invented. Where the rule is about such a key, it names what made the key match instead, which is a word from a closed list this server owns.
     */
    message: string;
};

/**
 * Problem
 *
 * A refusal, as RFC 9457 problem details.
 *
 * Served as `application/problem+json`. `type` and `instance` are
 * deliberately absent: an absent `type` means `about:blank`, which is
 * the truth here, since these problems are described by their status
 * and their prose rather than by a URI registry nobody serves.
 */
export type Problem = {
    /**
     * Title
     *
     * The status code's standard HTTP reason phrase, such as `Not Found`. It is the phrase and not a description of this API's own, because with `type` absent the problem type is `about:blank`, whose title RFC 9457 says should be the status's recommended phrase; a title of this server's own would imply a problem type the body does not identify. What was actually refused is `detail`.
     */
    title: string;
    /**
     * Status
     *
     * The HTTP status code, repeated in the body as the RFC describes, so that a problem separated from its response (in a log, in a bug report) still says what it was answered under.
     */
    status: number;
    /**
     * Detail
     *
     * What was refused and why, the same sentence the `vinga-server config` command prints for it. It names the entity the request addressed and the rule that was broken; it never quotes a secret, a configuration value that was rejected, or a key the request invented.
     */
    detail: string;
    /**
     * Errors
     *
     * The fields of the submitted body the refusal names, one entry each, for a client that wants to mark the offending field rather than show a paragraph. Present on every refusal and empty where there is no field to name: a body whose whole shape was wrong, a reference to another entity, a failure that was not the caller's. The entries are the same problems `detail` lists, in the same order and the same words.
     */
    errors: Array<FieldError>;
};

